\[
  \varphi\in\mathsf{WellFormedFormula}
\] means \(\varphi\in\WFF\), read as ``\(\varphi\) is a well-formed formula.''

\[
  \sigma\notin\mathsf{WellFormedFormula}
\] means the string \(\sigma\) is excluded by at least one formation-closed set containing \(\Prop\); equivalently, it is not generated by finitely many applications of the formation rules.

\begin{description}
  \item[Exposition.] A string fails to be well formed when it violates the formation grammar: an
operand may be missing, a connective may be missing, parentheses may be
unmatched, or the string may not be generated by finitely many formation steps.
\end{description}

\begin{description}
  \item[Exposition.] The named branch below records the displayed failure mode.
\item[\(\mathsf{WellFormedFormula}\) fails.] \[
\underbrace{P\land}_{\text{missing right operand}}
\qquad
\underbrace{(P\ Q)}_{\text{missing binary connective}}
\qquad
\underbrace{\neg\lor P}_{\text{negation applied to a non-formula}}.
\]
  In predicate-reading form this is recorded as
  \[
    \sigma\notin\mathsf{WellFormedFormula}
  \]
\end{description}

