support_blocks.body_tex:
\[
\begin{aligned}
\neg\text{Removable}
&\Longleftrightarrow
\forall L \in \mathbb{R}\;
\bigl(\lim_{x \to x_0} f(x) \ne L \lor L = f(x_0)\bigr),\\
\neg\text{Jump}
&\Longleftrightarrow
\forall L_-,L_+ \in \mathbb{R}\;
\bigl(\lim_{x \to x_0^-} f(x)\ne L_-
\lor \lim_{x \to x_0^+} f(x)\ne L_+
\lor L_-=L_+\bigr),\\
\neg\text{Essential}
&\Longleftrightarrow
\text{Removable}.
\end{aligned}
\]

\begin{description}
  \item[Exposition.]
\begin{itemize}
\item Removable discontinuity fails when no bilateral limit exists at $x_0$, or when the bilateral limit exists but equals $f(x_0)$ (making the function actually continuous).
\item Jump discontinuity fails when at least one of the one-sided limits does not exist, or when both one-sided limits exist but are equal (making it potentially removable or continuous).
\item Essential discontinuity fails when the discontinuity is removable (the bilateral limit exists and differs from $f(x_0)$).
\end{itemize}


  \item[\(\operatorname{IsRemovableDiscontinuity}.\)]
  The displayed obstruction is the corresponding failure mode.
  \[
\begin{aligned}
\neg\text{Removable}
&\Longleftrightarrow
\forall L \in \mathbb{R}\;
\bigl(\lim_{x \to x_0} f(x) \ne L \lor L = f(x_0)\bigr),\\
\neg\text{Jump}
&\Longleftrightarrow
\forall L_-,L_+ \in \mathbb{R}\;
\bigl(\lim_{x \to x_0^-} f(x)\ne L_-
\lor \lim_{x \to x_0^+} f(x)\ne L_+
\lor L_-=L_+\bigr),\\
\neg\text{Essential}
&\Longleftrightarrow
\text{Removable}.
\end{aligned}
  \]
  \[
\begin{aligned}
\neg \operatorname{IsRemovableDiscontinuity}(f,x_0,\mathbb{R},\mathbb{R}) &\Longleftrightarrow \forall L \in \mathbb{R}\; \bigl(\neg\operatorname{TendsTo}(f,A,x_0,L,\mathbb{R}) \lor L = f(x_0)\bigr).\\
\neg \operatorname{IsJumpDiscontinuity}(f,x_0,\mathbb{R},\mathbb{R}) &\Longleftrightarrow \forall L_{-}, L_{+} \in \mathbb{R}\; \bigl(\neg\operatorname{LeftLimit}(f,A,x_0,L_{-},\mathbb{R}) \lor \neg\operatorname{RightLimit}(f,A,x_0,L_{+},\mathbb{R}) \lor L_{-} = L_{+}\bigr).\\
\neg \operatorname{IsEssentialDiscontinuity}(f,x_0,\mathbb{R},\mathbb{R}) &\Longleftrightarrow \operatorname{IsRemovableDiscontinuity}(f,x_0,\mathbb{R},\mathbb{R}).
\end{aligned}
  \]
\end{description}

