\[
\begin{aligned}
\text{\((X,\mathcal{A})\) is a measurable space}
\Longleftrightarrow\;&
\mathcal{A}\subseteq\mathcal{P}(X)
\land X\in\mathcal{A}
\\
&{}\land
\forall E\in\mathcal{A}{:}\;X\setminus E\in\mathcal{A}
\\
&{}\land
\forall (E_n)_{n\in\mathbb{N}}\subseteq\mathcal{A}{:}\;
\bigcup_{n=1}^{\infty}E_n\in\mathcal{A}.
\end{aligned}
\]

