for all $a, b, c \in S$:
\begin{enumerate}
  \item \textbf{Reflexivity:} $a \leq a$.
  \item \textbf{Anti-symmetry:} $a \leq b \land b \leq a \Longrightarrow a = b$.
  \item \textbf{Transitivity:} $a \leq b \land b \leq c \Longrightarrow a \leq c$.
